    public static final String f15578a0 = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Accelerometer</title>\n<style>\nbody { margin:0; font-family: system-ui, sans-serif; background:#0f172a; color:#f8fafc; display:flex; flex-direction:column; align-items:center; justify-content:center; height:100vh; }\nbutton { padding:18px 36px; border:none; border-radius:16px; background:#00e5cc; color:#000; font-size:18px; font-weight:700; margin:12px; cursor:pointer; }\nbutton:active { opacity:0.8; }\npre { background:#1e293b; padding:16px; border-radius:12px; color:#00e5cc; font-size:14px; max-width:340px; width:90%; }\np { color:#94a3b8; max-width:300px; text-align:center; }\n</style>\n</head>\n<body>\n<h1>Accelerometer</h1>\n<p>Read acceleration on X, Y and Z axes.</p>\n<button onclick=\"AndroidAPI.startSensor('accelerometer', 'acc1')\">Start</button>\n<button onclick=\"AndroidAPI.stopSensor('accelerometer')\">Stop</button>\n<pre id=\"out\"></pre>\n<script>\nwindow.onAndroidEvent = function(event, data) {\n    if (event === 'sensorData' && data.sensor === 'accelerometer') {\n        document.getElementById('out').textContent = data.values.map(function(v){return v.toFixed(2);}).join(' | ');\n    }\n};\n</script>\n</body>\n</html>";

