    public static final String f15584d0 = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Step Counter</title>\n<style>\nbody { margin:0; font-family: system-ui, sans-serif; background:#0f172a; color:#f8fafc; display:flex; flex-direction:column; align-items:center; justify-content:center; height:100vh; }\nbutton { padding:18px 36px; border:none; border-radius:16px; background:#00e5cc; color:#000; font-size:18px; font-weight:700; margin:12px; cursor:pointer; }\nbutton:active { opacity:0.8; }\n.steps { font-size:48px; font-weight:bold; color:#00e5cc; margin:16px 0; }\np { color:#94a3b8; max-width:300px; text-align:center; }\n</style>\n</head>\n<body>\n<h1>Step Counter</h1>\n<p>Count steps using the hardware step sensor.</p>\n<button onclick=\"AndroidAPI.requestPermission('android.permission.ACTIVITY_RECOGNITION','stepPerm')\">Request Permission</button>\n<button onclick=\"AndroidAPI.startSensor('stepCounter', 'step1')\">Start</button>\n<button onclick=\"AndroidAPI.stopSensor('stepCounter')\">Stop</button>\n<div class=\"steps\" id=\"steps\">--</div>\n<script>\nwindow.onAndroidEvent = function(event, data) {\n    if (event === 'sensorData' && data.sensor === 'stepCounter') {\n        document.getElementById('steps').textContent = Math.floor(data.values[0]);\n    }\n};\n</script>\n</body>\n</html>";

