    /* renamed from: t0, reason: collision with root package name */
    public static final String f15606t0 = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Local Storage</title>\n<style>\nbody { margin: 0; font-family: system-ui, sans-serif; background: #0f172a; color: #f8fafc; padding: 20px; }\nh1 { font-size: 22px; text-align: center; }\n.card { max-width: 400px; margin: 20px auto; background: #151c2e; border-radius: 16px; padding: 16px; border: 1px solid #1f2937; }\ninput, textarea { width: 100%; padding: 12px; border-radius: 12px; border: 1px solid #1f2937; background: #111827; color: #f8fafc; margin-bottom: 10px; font-size: 14px; }\nbutton { width: 100%; padding: 14px; border: none; border-radius: 12px; background: #00e5cc; color: #000; font-weight: 700; cursor: pointer; margin-bottom: 8px; }\nbutton.secondary { background: #334155; color: #f8fafc; }\npre { background: #111827; padding: 12px; border-radius: 10px; color: #00e5cc; white-space: pre-wrap; }\n</style>\n</head>\n<body>\n<h1>App-private Notes</h1>\n<div class=\"card\">\n  <input id=\"fileName\" value=\"notes.txt\" />\n  <textarea id=\"content\" rows=\"4\" placeholder=\"Write something...\"></textarea>\n  <button onclick=\"save()\">Save Note</button>\n  <button class=\"secondary\" onclick=\"load()\">Load Note</button>\n  <pre id=\"out\">Ready</pre>\n</div>\n<script>\nfunction save() {\n  var name = document.getElementById('fileName').value;\n  var text = document.getElementById('content').value;\n  var ok = AndroidAPI.writeAppFile(name, text);\n  document.getElementById('out').textContent = ok ? 'Saved!' : 'Save failed';\n}\nfunction load() {\n  var name = document.getElementById('fileName').value;\n  var text = AndroidAPI.readAppFile(name);\n  document.getElementById('content').value = text;\n  document.getElementById('out').textContent = text ? 'Loaded.' : 'No note found';\n}\n</script>\n</body>\n</html>";

